import type { QAActionItems } from './qa-action-items-model';
import type { MainDBQA } from './main-dbqa-model';

export const QASubActionItemsVerificationStatusKeyToLabel = {
  'VerificationStatusKey0': 'Pending',
  'VerificationStatusKey1': 'Verified',
  'VerificationStatusKey2': 'Rejected'
} as const;
export type QASubActionItemsVerificationStatusKey = keyof typeof QASubActionItemsVerificationStatusKeyToLabel;

export interface QASubActionItems {
  /**
   * @displayName ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: number;
  /**
   * @displayName Title
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  title: string;
  /**
   * @displayName ActionItemRef
   */
  actionItemRef?: Pick<QAActionItems, 'id' | 'title'>;
  /**
   * @displayName ParentRecord
   */
  parentRecord?: Pick<MainDBQA, 'id' | 'title'>;
  /**
   * @displayName Sub Action Row No
   */
  subActionRowNo?: number;
  /**
   * @displayName Sub-Task Description
   */
  subTaskDescription?: string;
  /**
   * @displayName Verification Status
   */
  verificationStatusKey?: QASubActionItemsVerificationStatusKey;
  /**
   * @displayName Verified By
   */
  verifiedBy?: string;
  /**
   * @displayName Verified Date
   */
  verifiedDate?: string;
}

export const _QASubActionItems = 'QASubActionItems' as const;